**Gates before launch.** I run four gates in order, and a failure at any one means I halt and report instead of launching. First, I check that spe/predictions/r04.yaml and spe/plans/r04.md are in HEAD and unchanged, with `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md`. Second, the grader selftest runs grade.py three times. An oracle file built from spe/evals/tasks/answers.json must score 1.0 on category and on priority. An empty file and a file with every label wrong must both fail. The selftest also checks that answers.json holds exactly 50 tickets and that their ids match `args.tickets`, because the eval set had 40 tickets before this round. I also run judge.md on 2 known-good and 2 known-bad replies to confirm it can tell them apart. Third, the control regrades round 3's saved outputs with this round's grade.py. I chose spe/runs/r03 as their location, which is the folder I assume r03-workflow.js wrote to. The control must reproduce the round 3 numbers in spe/prediction-log.md. If a number changes, the grader changed, so I log that and halt before any trial runs. Fourth, the dry run uses `{dryRun: true, trials: 1, only: ['B:<id1>', 'C2:<id1>', 'C2:<id2>']}` and writes to spe/runs/r04-dry. It passes when four things hold:
1. Every trial matches the schema.
2. grade.py and the judge return a row for every trial.
3. No trial is voided.
4. The measured cost per trial gives an `estTrialUsd` that keeps 500 trials plus judging under $40.

I save the script as spe/evals/harness/r04-workflow.js before the dry run. After all gates pass, I commit it locally as "spe r04: evaluate harness" and do not push. Then I launch with all 50 ticket ids.

```js
export const meta = {
  name: 'triage-spe-eval',
  description: 'SPE eval for the triage agent. Runs each config on the fixed ticket set, grades labels with code, judges reply tone with Opus, tops up split cells, scans for peeks, and ends with failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Scan' },
    { title: 'Synthesis' },
  ],
};

// Defaults carried over from r03-workflow.js and not re-checked here:
// - args.runner is the r03 ticket runner. Each call runs one triage trial in its own process
//   and prints JSON with label, reply, usage, cost_usd, runtime_ms, tool_calls, tool_errors.
// - args.gradeCmd is the grade.py command line that the selftest gate used.
// - The spend cap covers measured runner API spend plus estimated judge spend.
//   Driver, grader, and critic agents are limited by count through args.maxAgents.

const ROUND = 4;
const pad = (n) => String(n).padStart(2, '0');
const RR = `r${pad(ROUND)}`;

const A = {
  configs: ['B', 'C2'],
  tickets: [],
  expectTickets: 50,
  trials: 5,
  spendCapUsd: 40,
  estTrialUsd: 0.04,
  estJudgeBatchUsd: 0.3,
  judgeBatchSize: 10,
  topupPerCell: 5,
  topupMaxTrials: 60,
  maxAgents: 250,
  runner: 'node triage/bin/run-ticket.js',
  gradeCmd: 'python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --json --runs',
  transcriptDir: null,
  only: null,
  dryRun: false,
  agentModel: 'opus',
  judgeModel: 'opus',
  ...(args && typeof args === 'object' ? args : {}),
};
const RUN_DIR = A.dryRun ? `spe/runs/${RR}-dry` : `spe/runs/${RR}`;

// ---------- cells ----------
let cells;
if (A.only) {
  cells = A.only.map((key) => {
    const [cfg, ticket] = key.split(':');
    return { cfg, ticket, key };
  });
} else {
  if (A.tickets.length !== A.expectTickets) {
    throw new Error(`Expected ${A.expectTickets} tickets but got ${A.tickets.length}. Halting.`);
  }
  cells = [];
  for (const cfg of A.configs) for (const ticket of A.tickets) cells.push({ cfg, ticket, key: `${cfg}:${ticket}` });
}
const configsInRun = [...new Set(cells.map((c) => c.cfg))];

// ---------- budget ----------
let spent = 0;
let reserved = 0;
let agentsUsed = 0;
const skips = [];

function tryReserve(usd, what) {
  if (agentsUsed + 1 > A.maxAgents) {
    skips.push({ what, reason: 'agent cap', cap: A.maxAgents });
    log(`SKIP ${what}: agent cap ${A.maxAgents} reached.`);
    return false;
  }
  if (spent + reserved + usd > A.spendCapUsd) {
    skips.push({ what, reason: 'spend cap', spent: +spent.toFixed(2), needed: usd });
    log(`SKIP ${what}: $${(spent + reserved).toFixed(2)} + $${usd.toFixed(2)} would cross the $${A.spendCapUsd} cap.`);
    return false;
  }
  reserved += usd;
  agentsUsed += 1;
  return true;
}
function settle(reservedUsd, actualUsd) {
  reserved -= reservedUsd;
  spent += actualUsd;
}

// ---------- helpers ----------
function shuffled(arr, seed) {
  const a = arr.slice();
  let s = seed >>> 0 || 1;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 1664525 + 1013904223) >>> 0;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function chunk(arr, n) {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
}
function peeks(commands, dir) {
  return commands.filter((c) => {
    const rest = c.split(dir).join('');
    return /spe\//.test(rest) || /answers\.json|grade\.py|judge\.md|r\d\d(-draft)?\.yaml/.test(rest);
  });
}

// ---------- schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['runs', 'commands'],
  properties: {
    commands: { type: 'array', items: { type: 'string' } },
    runs: {
      type: 'array',
      items: {
        type: 'object',
        required: ['k', 'status'],
        properties: {
          k: { type: 'integer' },
          status: { type: 'string', enum: ['completed', 'harness_error'] },
          error: { type: 'string' },
          category: { type: 'string' },
          priority: { type: 'string' },
          reply: { type: 'string' },
          runtime_ms: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          input_tokens: { type: 'integer' },
          output_tokens: { type: 'integer' },
          cost_usd: { type: 'number' },
        },
      },
    },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['status', 'results'],
  properties: {
    status: { type: 'string', enum: ['ok', 'grader_error'] },
    error: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['ticket', 'k', 'category_ok', 'priority_ok'],
        properties: {
          ticket: { type: 'string' },
          k: { type: 'integer' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          expected_category: { type: 'string' },
          expected_priority: { type: 'string' },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'score', 'pass', 'reason'],
        properties: {
          id: { type: 'string' },
          score: { type: 'number' },
          pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['touched'],
  properties: {
    touched: {
      type: 'array',
      items: {
        type: 'object',
        required: ['label', 'path'],
        properties: { label: { type: 'string' }, path: { type: 'string' } },
      },
    },
  },
};

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          id: { type: 'string' },
          name: { type: 'string' },
          kind: { type: 'string', enum: ['model', 'prompt', 'tool', 'harness', 'grader', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
        },
      },
    },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
  },
};

// ---------- trial driver ----------
function driverPrompt(cell, ks, dir) {
  return [
    'You are a test driver. Your only job is to run the triage agent on one support ticket and copy back what it produced.',
    '',
    `You may run the commands below. You may read and write files only under ${dir}/.`,
    'Do not open, list, search, or print anything else under spe/. Do not look for correct labels, answer keys, rubrics, or predictions.',
    "Do not edit, retry, or improve the agent's output.",
    '',
    'Run these commands one at a time. Each one is a separate trial in its own process:',
    ...ks.map((k) => `  mkdir -p ${dir} && ${A.runner} --config ${cell.cfg} --ticket ${cell.ticket} --json > ${dir}/t${k}.json`),
    '',
    'Then read each output file and return one entry per trial. Set k to the number in the file name.',
    'Copy label.category to category and label.priority to priority. Copy reply, input_tokens, output_tokens, cost_usd, runtime_ms, tool_calls, and tool_errors exactly as written.',
    'If a run crashed, timed out, printed invalid JSON, or hit a rate limit, set status to "harness_error" and copy the error text.',
    'Otherwise set status to "completed", even if the labels look wrong to you.',
    'List every shell command you ran in commands, word for word.',
  ].join('\n');
}

async function runDriver(cell, startK, n, phaseName) {
  const ks = Array.from({ length: n }, (_, i) => startK + i);
  const what = `${cell.key} k${ks[0]}-${ks[ks.length - 1]}`;
  const est = n * A.estTrialUsd;
  if (!tryReserve(est, what)) return null;
  const dir = `${RUN_DIR}/${cell.cfg}/${cell.ticket}`;
  let res;
  try {
    res = await agent(driverPrompt(cell, ks, dir), {
      label: `trial ${what}`,
      phase: phaseName,
      schema: TRIAL_SCHEMA,
      model: A.agentModel,
    });
  } catch (e) {
    settle(est, est);
    log(`HARNESS ERROR ${what}: ${String(e)}`);
    return { cell, voided: false, peeked: [], runs: ks.map((k) => ({ k, status: 'harness_error', error: String(e) })) };
  }
  settle(est, res.runs.reduce((s, r) => s + (r.cost_usd || 0), 0));
  const peeked = peeks(res.commands || [], dir);
  if (peeked.length) log(`VOID ${what}: commands touched forbidden paths: ${peeked.join(' | ')}`);
  return { cell, voided: peeked.length > 0, peeked, runs: res.runs };
}

function flatten(batches) {
  const out = [];
  for (const b of batches) {
    for (const r of b.runs) {
      out.push({ ...r, cfg: b.cell.cfg, ticket: b.cell.ticket, key: b.cell.key, voided: b.voided, topup: r.k > A.trials });
    }
  }
  return out;
}

// ---------- grader ----------
async function grade(cfg, phaseName) {
  if (!tryReserve(0, `grade ${cfg}`)) throw new Error(`Agent cap reached before grading ${cfg}. Halting.`);
  const r = await agent(
    [
      'Run the code grader and report its output. Do not grade anything yourself and do not change any file.',
      `Run exactly: ${A.gradeCmd} ${RUN_DIR}/${cfg}`,
      'Return one result per trial file that grade.py scored. Copy ticket, k, category_ok, priority_ok, expected_category, and expected_priority from its output.',
      'If grade.py exits non-zero or prints no results, set status to "grader_error" and copy stderr into error.',
    ].join('\n'),
    { label: `grade ${cfg}`, phase: phaseName, schema: GRADE_SCHEMA, model: A.agentModel },
  );
  settle(0, 0);
  if (r.status !== 'ok') throw new Error(`grade.py failed on ${cfg}: ${r.error}. A broken grader is a halt condition.`);
  return r.results;
}

function attachGrades(trials, cfg, results) {
  const m = new Map(results.map((g) => [`${g.ticket}:${g.k}`, g]));
  for (const t of trials) {
    if (t.cfg !== cfg) continue;
    const g = m.get(`${t.ticket}:${t.k}`);
    if (g) t.grade = { ...g, both_ok: g.category_ok && g.priority_ok };
  }
}

// ================= Trials =================
phase('Trials');
log(`Round ${ROUND}. ${cells.length} cells x ${A.trials} trials. Spend cap $${A.spendCapUsd}. Agent cap ${A.maxAgents}. Output folder ${RUN_DIR}.`);
const primaryBatches = (await parallel(cells.map((c) => () => runDriver(c, 1, A.trials, 'Trials')))).filter(Boolean);
const trials = flatten(primaryBatches);
log(`Trials done. ${trials.filter((t) => t.status === 'completed').length} completed, ${trials.filter((t) => t.status === 'harness_error').length} harness errors, spend $${spent.toFixed(2)}.`);

// ================= Grade =================
phase('Grade');
for (const cfg of configsInRun) attachGrades(trials, cfg, await grade(cfg, 'Grade'));
const ungraded = trials.filter((t) => t.status === 'completed' && !t.grade);
if (ungraded.length) log(`WARNING ${ungraded.length} completed trials have no grade row: ${ungraded.slice(0, 10).map((t) => `${t.key}:${t.k}`).join(', ')}`);

// ================= Judge =================
phase('Judge');
const JUDGE_NOTE = 'The judge is Opus. Opus is in the same model family as the Sonnet trials, and no judge from another family is available, so tone scores may share the trial model\'s blind spots.';
log(JUDGE_NOTE);
const toJudge = [];
for (const t of trials) {
  if (t.status !== 'completed' || t.voided || t.topup) continue;
  if (!t.reply || !t.reply.trim()) {
    t.tone = { score: 0, pass: false, reason: 'empty reply, not sent to judge' };
    continue;
  }
  toJudge.push(t);
}
const anon = shuffled(toJudge, ROUND * 7919).map((t, i) => ({ id: `R${String(i + 1).padStart(4, '0')}`, t }));
const byId = new Map(anon.map((a) => [a.id, a.t]));
const judgeBatches = chunk(anon, A.judgeBatchSize);
await parallel(
  judgeBatches.map((batch, bi) => async () => {
    const what = `judge batch ${bi + 1}/${judgeBatches.length}`;
    if (!tryReserve(A.estJudgeBatchUsd, what)) return;
    const items = batch.map((a) => ({ id: a.id, ticket: a.t.ticket, reply: a.t.reply }));
    const r = await agent(
      [
        'You are grading drafted support replies for tone.',
        'Read spe/evals/graders/judge.md and apply its rubric exactly. Use no other standard.',
        'Each item has an anonymous id, a ticket id, and the drafted reply. Read the ticket text from the location judge.md names.',
        'You are not told which system wrote each reply. Do not guess it.',
        'Return one entry per id with the score, pass as judge.md defines it, and a one-line reason.',
        '',
        JSON.stringify(items, null, 1),
      ].join('\n'),
      { label: what, phase: 'Judge', schema: JUDGE_SCHEMA, model: A.judgeModel },
    );
    settle(A.estJudgeBatchUsd, A.estJudgeBatchUsd);
    for (const s of r.scores) {
      const t = byId.get(s.id);
      if (t) t.tone = { score: s.score, pass: s.pass, reason: s.reason };
    }
  }),
);
log(`Judge spend is estimated at $${A.estJudgeBatchUsd} per batch, not measured. Spend so far $${spent.toFixed(2)}.`);

// ================= Top-up =================
phase('Top-up');
// The headline numbers use only the first A.trials trials per cell, as the approved plan says.
// Top-up trials resolve split cells on labels only and are reported separately.
const primaryByCell = new Map();
for (const t of trials) {
  if (t.topup || t.status !== 'completed' || t.voided || !t.grade) continue;
  if (!primaryByCell.has(t.key)) primaryByCell.set(t.key, []);
  primaryByCell.get(t.key).push(t);
}
const splitCells = cells.filter((c) => {
  const ts = primaryByCell.get(c.key) || [];
  const passes = ts.filter((t) => t.grade.both_ok).length;
  return passes > 0 && passes < ts.length;
});
log(`${splitCells.length} split cells. Top-up cap ${A.topupMaxTrials} trials, ${A.topupPerCell} per cell.`);
let topupLeft = A.topupMaxTrials;
const topupJobs = [];
for (const c of splitCells) {
  const n = Math.min(A.topupPerCell, topupLeft);
  if (n <= 0) {
    skips.push({ what: `top-up ${c.key}`, reason: 'top-up cap' });
    log(`SKIP top-up ${c.key}: top-up cap reached.`);
    continue;
  }
  topupLeft -= n;
  topupJobs.push({ c, n });
}
const topupBatches = (await parallel(topupJobs.map(({ c, n }) => () => runDriver(c, A.trials + 1, n, 'Top-up')))).filter(Boolean);
const topupTrials = flatten(topupBatches);
trials.push(...topupTrials);
if (topupTrials.length) {
  for (const cfg of [...new Set(topupTrials.map((t) => t.cfg))]) attachGrades(trials, cfg, await grade(cfg, 'Top-up'));
}

// ================= Scan =================
phase('Scan');
if (A.transcriptDir && tryReserve(0, 'transcript scan')) {
  const r = await agent(
    [
      `Search the subagent transcripts under ${A.transcriptDir} for this Workflow run.`,
      'Look only at transcripts whose label starts with "trial ".',
      'Report every place where such a transcript read, listed, searched, or printed a path under spe/evals/, spe/predictions/, spe/plans/, spe/spec/, spe/prediction-log.md, spe/failures.md, or any spe/runs/ folder other than its own output folder.',
      'Do not open the files those paths point to. Return the transcript label and the path for each hit, or an empty list.',
    ].join('\n'),
    { label: 'transcript scan', phase: 'Scan', schema: SCAN_SCHEMA, model: A.agentModel },
  );
  settle(0, 0);
  for (const hit of r.touched) {
    const m = /^trial (\S+) k(\d+)-(\d+)/.exec(hit.label);
    if (!m) continue;
    const [, key, lo, hi] = m;
    for (const t of trials) {
      if (t.key === key && t.k >= +lo && t.k <= +hi && !t.voided) {
        t.voided = true;
        log(`VOID ${key}:${t.k}: transcript touched ${hit.path}`);
      }
    }
  }
} else {
  log('Transcript scan did not run in-script. Run it at close-out on this Workflow\'s transcripts before using any number.');
}

// ================= Synthesis =================
phase('Synthesis');
function summarize(list) {
  const done = list.filter((t) => t.status === 'completed' && !t.voided && t.grade);
  const n = done.length;
  const rate = (f) => (n ? +(done.filter(f).length / n).toFixed(3) : null);
  const mean = (f) => (n ? +(done.reduce((s, t) => s + (f(t) || 0), 0) / n).toFixed(1) : null);
  const judged = done.filter((t) => t.tone);
  const calls = done.reduce((s, t) => s + (t.tool_calls || 0), 0);
  const errs = done.reduce((s, t) => s + (t.tool_errors || 0), 0);
  return {
    completed: n,
    voided: list.filter((t) => t.voided).length,
    harness_errors: list.filter((t) => t.status === 'harness_error').length,
    category_acc: rate((t) => t.grade.category_ok),
    priority_acc: rate((t) => t.grade.priority_ok),
    both_acc: rate((t) => t.grade.both_ok),
    tone_pass: judged.length ? +(judged.filter((t) => t.tone.pass).length / judged.length).toFixed(3) : null,
    tone_judged: judged.length,
    runtime_ms_mean: mean((t) => t.runtime_ms),
    tool_calls_mean: mean((t) => t.tool_calls),
    tool_error_rate: calls ? +(errs / calls).toFixed(3) : null,
    tokens_mean: mean((t) => (t.input_tokens || 0) + (t.output_tokens || 0)),
    cost_usd: +done.reduce((s, t) => s + (t.cost_usd || 0), 0).toFixed(2),
  };
}

const perConfig = {};
for (const cfg of configsInRun) perConfig[cfg] = summarize(trials.filter((t) => t.cfg === cfg && !t.topup));

const topupSummary = splitCells.map((c) => {
  const all = trials.filter((t) => t.key === c.key && t.status === 'completed' && !t.voided && t.grade);
  return {
    cell: c.key,
    primary_both_acc: summarize(all.filter((t) => !t.topup)).both_acc,
    with_topup_both_acc: summarize(all).both_acc,
    n_total: all.length,
  };
});

const coverage = cells.map((c) => {
  const ts = trials.filter((t) => t.key === c.key && !t.topup);
  return {
    cell: c.key,
    expected: A.trials,
    ran: ts.length,
    completed: ts.filter((t) => t.status === 'completed').length,
    graded: ts.filter((t) => t.grade).length,
    judged: ts.filter((t) => t.tone).length,
    voided: ts.filter((t) => t.voided).length,
  };
});

const failures = trials
  .filter((t) => !t.voided && (t.status === 'harness_error' || (t.grade && !t.grade.both_ok) || (t.tone && !t.tone.pass)))
  .map((t) => ({
    trial: `${t.key}:${t.k}`,
    status: t.status,
    error: t.error,
    got: t.grade ? `${t.category}/${t.priority}` : undefined,
    expected: t.grade ? `${t.grade.expected_category}/${t.grade.expected_priority}` : undefined,
    tone: t.tone && !t.tone.pass ? t.tone.reason : undefined,
    tool_errors: t.tool_errors,
  }));

let failureAnalysis = null;
if (tryReserve(0, 'failure analysis')) {
  failureAnalysis = await agent(
    [
      `These are the failed trials from round ${ROUND} of the triage eval. Group them into failure types.`,
      'Read spe/failures.md. Reuse an existing F-number when a type matches. Give each new type the id "new".',
      'Treat harness errors and rate limits as harness problems, not model failures.',
      'Do not read spe/predictions/. Do not edit any file.',
      '',
      JSON.stringify(failures.slice(0, 400), null, 1),
    ].join('\n'),
    { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: A.agentModel },
  );
  settle(0, 0);
}

let critic = null;
if (tryReserve(0, 'completeness critic')) {
  critic = await agent(
    [
      `Check whether this eval run of round ${ROUND} is complete enough to score. Do not edit any file.`,
      `The plan was ${A.trials} trials per cell, configs ${A.configs.join(' and ')}, ${A.expectTickets} tickets, code grading of category and priority, an Opus tone judge, and a $${A.spendCapUsd} cap.`,
      'List every gap: cells short of trials without a logged skip, completed trials without a grade or a tone score, voided trials, harness error clusters, a missing transcript scan, and anything in the failure analysis that points to a grader bug.',
      '',
      JSON.stringify({ coverage, skips, perConfig, transcriptScan: Boolean(A.transcriptDir), judgeNote: JUDGE_NOTE, failureTypes: failureAnalysis && failureAnalysis.types }, null, 1),
    ].join('\n'),
    { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: A.agentModel },
  );
  settle(0, 0);
}

log(`Done. Spend $${spent.toFixed(2)} of $${A.spendCapUsd}. Agents ${agentsUsed} of ${A.maxAgents}. Skips ${skips.length}.`);

return {
  round: ROUND,
  dryRun: A.dryRun,
  runDir: RUN_DIR,
  configs: perConfig,
  topup: topupSummary,
  coverage,
  spend: { spent_usd: +spent.toFixed(2), cap_usd: A.spendCapUsd, judge_spend_estimated: true },
  agents_used: agentsUsed,
  skips,
  voids: trials.filter((t) => t.voided).map((t) => `${t.key}:${t.k}`),
  judge_note: JUDGE_NOTE,
  failure_analysis: failureAnalysis,
  critic,
};
```
